@startuml

class InsuranceCompany {
  + CompanyName : string
  + RegistrationNumber : string
}

class PolicyType {
  + TypeName : string
}

class Policy {
  + PolicyNumber : string
  + CoverageAmount : double
  + ExpirationDate : date
}

class Customer {
  + CustomerId : int
  + Name : string
  + ContactNumber : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "0..*" Policy
InsuranceCompany "1" -- "0..*" Customer
Customer "1" -- "0..*" Contract
Contract "1" -- "1" Policy
Policy "1" -- "1" PolicyType

@enduml

